import type { ReactNode } from "react";
import { SectionHeader } from "@/shared/ui/layout/SectionHeader";

export interface PageHeaderProps {
  title?: ReactNode;
  hint?: ReactNode;
  toolbar?: ReactNode;
  meta?: ReactNode;
}
export function PageHeader({ title = "Page title", hint, toolbar, meta }: PageHeaderProps) {
  return (
    <div style={{ padding: "10px 16px", background: "var(--bg-elev)", flex: "none", borderBottom: "1px solid var(--border-soft)" }}>
      <SectionHeader title={title} hint={hint} right={toolbar} meta={meta} />
    </div>
  );
}
